    help = "مخزن واقعی ذینفعان سایپا یدک (۱۷۷ ردیف) را جایگزین می‌کند."

    def handle(self, *args, **options):
        Stakeholder.objects.all().delete()
        for r in ROWS:
            Stakeholder.objects.create(**r)
        self.stdout.write(self.style.SUCCESS(f"{len(ROWS)} ردیف واقعی ذینفعان ثبت شد."))
